<script setup lang="ts">
import type { PublicArticle } from '../../../../packages/contracts/src/index';
import type { Programme } from '../../../../packages/contracts/src/programme';
import type { ListeningState,ListeningProgress } from '../../../../packages/contracts/src/member';
type Bookmark={articleId:string;savedVersionId:string;createdAt:string;status:string;article:{slug:string;headline:string;correction:string|null}|null};
const member=useMember(),player=useProgrammeAudio();const bookmarks=ref<Bookmark[]>([]),listening=ref<ListeningState|null>(null),articles=ref<PublicArticle[]>([]),programmes=ref<Programme[]>([]),message=ref(''),busy=ref(false),selectedArticle=ref(''),selectedProgramme=ref('');
async function load(){await member.refresh();if(!member.session.value)return;try{const [b,l,a,p]=await Promise.all([$fetch<{data:Bookmark[]}>('/api/v1/me/bookmarks'),$fetch<{data:ListeningState}>('/api/v1/me/listening'),$fetch<{data:PublicArticle[]}>('/api/v1/articles'),$fetch<{data:Programme[]}>('/api/v1/programmes')]);bookmarks.value=b.data;listening.value=l.data;articles.value=a.data;programmes.value=p.data;}catch(e){message.value=memberError(e);}}
onMounted(load);
async function action(work:()=>Promise<unknown>){if(busy.value)return;busy.value=true;message.value='';try{await work();await load();message.value='Account updated.';}catch(e){message.value=memberError(e);}finally{busy.value=false;}}
const clipsOnly=ref(false);const shownBookmarks=computed(()=>clipsOnly.value?bookmarks.value.filter(b=>b.article&&programmes.value.some(p=>p.kind===`clip`&&p.articleSlugs.includes(b.article!.slug))):bookmarks.value);
const save=()=>action(()=>member.mutate(`/api/v1/me/bookmarks/${selectedArticle.value}`,'PUT',{}));
const remove=(id:string)=>action(()=>member.mutate(`/api/v1/me/bookmarks/${id}`,'DELETE',{}));
const updateQueue=(ids:string[])=>action(()=>member.mutate('/api/v1/me/queue','PUT',{revision:listening.value?.revision,programmeIds:ids}));
function move(index:number,direction:number){const ids=[...(listening.value?.queue||[])];const destination=index+direction;if(destination<0||destination>=ids.length)return;[ids[index],ids[destination]]=[ids[destination]!,ids[index]!];void updateQueue(ids);}
function label(id:string){return programmes.value.find(p=>p.programmeId===id)?.title||'Unavailable programme';}
function play(id:string,seconds=0){const programme=programmes.value.find(p=>p.programmeId===id);if(!programme){message.value='This programme is unavailable.';return;}if(programme.kind===`clip`){player.pause();void navigateTo(`/clips/${programme.programmeId}`);return;}player.setProgramme(programme,seconds);void player.play();}
function resume(progress:ListeningProgress){const programme=programmes.value.find(p=>p.programmeId===progress.programmeId);if(!programme){message.value='This programme is unavailable.';return;}if(programme.videoRendition?.renditionKey===progress.renditionKey){player.pause();void navigateTo({path:programme.kind==='clip'?`/clips/${programme.programmeId}`:'/newsroom',query:{programme:programme.programmeId,rendition:progress.renditionKey,position:String(progress.positionMs/1000)}});return;}if(programme.renditionKey!==progress.renditionKey){message.value='This saved rendition is no longer available. Choose the current programme from your queue.';return;}play(progress.programmeId,progress.positionMs/1000);}
async function clearHistory(){const detail={pending:[] as Promise<void>[]};window.dispatchEvent(new CustomEvent('aggregator:history-clear-request',{detail}));await Promise.all(detail.pending);await action(()=>member.mutate('/api/v1/me/progress','DELETE',{}));if(message.value==='Account updated.')window.dispatchEvent(new Event('aggregator:clear-history'));}
function importQueue(){const ids=player.queue.value.map(p=>p.programmeId);void updateQueue([...new Set([...(listening.value?.queue||[]),...ids])]);}
useHead({title:'My library — The Aggregator'});
</script>
<template><MemberFrame><h1>My library</h1><p v-if="!member.checked.value">Checking your session…</p><p v-else-if="!member.session.value">Keep saved stories and listening preferences across visits. <NuxtLink to="/sign-in?returnTo=/library">Sign in or create an account</NuxtLink></p><template v-if="member.session.value"><p>{{ member.session.value.user.displayName }} · local captured-mail account</p><button class="control control--quiet" @click="member.logout().catch(e=>message=memberError(e))">Sign out</button><h2>Saved stories</h2><ControlSwitch v-model="clipsOnly" label="Only stories with Clips"/><form class="member-form" @submit.prevent="save"><ControlCombobox label="Story" v-model="selectedArticle" :disabled="busy" :options="[{value:'',label:'Choose a story',disabled:true},...articles.map(a=>({value:a.id,label:a.headline}))]"/><button class="control control--primary" :disabled="busy||!selectedArticle">Save story</button></form><p v-if="!bookmarks.length">No stories saved yet.</p><article v-for="bookmark in shownBookmarks" :key="bookmark.articleId" class="member-card"><h3><NuxtLink v-if="bookmark.article" :to="`/articles/${bookmark.article.slug}`">{{ bookmark.article.headline }}</NuxtLink><span v-else>Saved story unavailable</span></h3><p v-if="!bookmark.article">This saved item is no longer available. Its content is not retained here.</p><p class="metadata">Saved {{ new Date(bookmark.createdAt).toLocaleDateString() }}</p><p v-if="bookmark.article?.correction">Correction: {{ bookmark.article.correction }}</p><button class="control control--quiet" :disabled="busy" @click="remove(bookmark.articleId)">Remove saved story</button></article><h2>Listening queue</h2><form class="member-form" @submit.prevent="updateQueue([...new Set([...(listening?.queue||[]),selectedProgramme])])"><ControlCombobox label="Prepared programme" v-model="selectedProgramme" :disabled="busy" :options="[{value:'',label:'Choose a programme',disabled:true},...programmes.map(p=>({value:p.programmeId,label:p.title+' · '+p.variant}))]"/><button class="control control--primary" :disabled="busy||!selectedProgramme">Add to queue</button></form><p v-if="!listening?.queue.length">Your account queue is empty.</p><article v-for="(id,index) in listening?.queue" :key="id" class="member-card"><h3>{{ index+1 }}. {{ label(id) }}</h3><div class="member-actions"><button class="control control--primary" @click="play(id)">Play</button><button class="control control--secondary" :disabled="busy||index===0" @click="move(index,-1)">Move up</button><button class="control control--secondary" :disabled="busy||index===(listening?.queue.length||0)-1" @click="move(index,1)">Move down</button><button class="control control--quiet" :disabled="busy" @click="updateQueue(listening!.queue.filter(item=>item!==id))">Remove</button></div></article><section v-if="player.queue.value.length" class="member-notice"><h3>Add your guest queue?</h3><p>Your anonymous queue is not copied automatically. This adds only queued programmes, not listening history.</p><button class="control control--secondary" :disabled="busy" @click="importQueue">Add guest queue to account</button></section><h2>Continue listening</h2><p v-if="!listening?.progress.length">No account listening progress saved.</p><article v-for="progress in listening?.progress" :key="progress.programmeId" class="member-card"><h3>{{ label(progress.programmeId) }}</h3><button class="control control--secondary" @click="resume(progress)">Resume at {{ audioTime(progress.positionMs/1000) }}</button></article><button class="control control--quiet" :disabled="busy" @click="clearHistory">Clear account listening history</button></template><p class="member-status" role="status">{{ message }}</p></MemberFrame></template>


